fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        // Empty array stays empty under any rotation.
        return Vec::new();
    }

    // Reduce the offset modulo n so it's within bounds [0, n).
    let k = offset % n;

    // Build the rotated array by taking the tail [k..] and then the head [0..k].
    let mut rotated = Vec::with_capacity(n);
    rotated.extend_from_slice(&a[k..]);
    rotated.extend_from_slice(&a[..k]);
    rotated
}

